use super::FromRecoveredTx;
use crate::ScrollTransactionIntoTxEnv;
use alloy_consensus::transaction::Recovered;
use alloy_eips::{Encodable2718, Typed2718};
use alloy_evm::{RecoveredTx, ToTxEnv};
use alloy_primitives::{Address, Bytes, TxKind, U256};
use revm::context::TxEnv;
use scroll_alloy_consensus::{ScrollTxEnvelope, TxL1Message};
pub use zstd_compression::{compute_compressed_size, compute_compression_ratio};

#[cfg(feature = "zstd_compression")]
mod zstd_compression {
    use super::*;
    use std::io::Write;

    use encoder_standard::{init_zstd_encoder, N_BLOCK_SIZE_TARGET};
    use revm_scroll::l1block::TX_L1_FEE_PRECISION_U256;

    /// Computes the compressed size for the provided bytes.
    ///
    /// This is computed as:
    /// `min(encoded_size, original_size)`
    pub fn compute_compressed_size<T: AsRef<[u8]>>(bytes: &T) -> usize {
        // Compressed size of empty data is 0.
        if bytes.as_ref().is_empty() {
            return 0;
        }

        // Instantiate the compressor
        let mut compressor = init_zstd_encoder(N_BLOCK_SIZE_TARGET);

        // Set the pledged source size to the length of the bytes
        // and write the bytes to the compressor.
        let original_bytes_len = bytes.as_ref().len();
        compressor
            .set_pledged_src_size(Some(original_bytes_len as u64))
            .expect("failed to set pledged source size");
        compressor.write_all(bytes.as_ref()).expect("failed to write bytes to compressor");

        // Finish the compression and get the result.
        let result = compressor.finish().expect("failed to finish compression");
        let encoded_bytes_len = result.len();

        if encoded_bytes_len > original_bytes_len {
            original_bytes_len
        } else {
            encoded_bytes_len
        }
    }

    /// Computes the compression ratio for the provided bytes.
    ///
    /// This is computed as:
    /// `max(1, original_size * TX_L1_FEE_PRECISION_U256 / encoded_size)`
    pub fn compute_compression_ratio<T: AsRef<[u8]>>(bytes: &T) -> U256 {
        // By definition, the compression ratio of empty data is infinity
        if bytes.as_ref().is_empty() {
            return U256::MAX
        }

        let original_bytes_len = bytes.as_ref().len();
        let encoded_bytes_len = compute_compressed_size(bytes);

        if encoded_bytes_len == original_bytes_len {
            return TX_L1_FEE_PRECISION_U256;
        }

        // compression_ratio(tx) = size(tx) * PRECISION / size(zstd(tx))
        U256::from(original_bytes_len)
            .saturating_mul(TX_L1_FEE_PRECISION_U256)
            .wrapping_div(U256::from(encoded_bytes_len))
    }
}

#[cfg(not(feature = "zstd_compression"))]
mod zstd_compression {
    use super::*;

    /// Computes the compressed size for the provided bytes. This panics if the compression
    /// feature is not enabled. This is to support `no_std` environments where zstd is not
    /// available.
    pub fn compute_compressed_size<T: AsRef<[u8]>>(bytes: &T) -> usize {
        panic!("Compression feature is not enabled. Please enable the 'compression' feature to use this function.");
    }

    /// Computes the compression ratio for the provided bytes. This panics if the compression
    /// feature is not enabled. This is to support `no_std` environments where zstd is not
    /// available.
    pub fn compute_compression_ratio<T: AsRef<[u8]>>(_bytes: &T) -> U256 {
        panic!("Compression feature is not enabled. Please enable the 'compression' feature to use this function.");
    }
}

/// A generic wrapper for a type that includes compression info and encoded bytes.
#[derive(Debug, Clone)]
pub struct WithCompressionInfo<T> {
    // The original value.
    value: T,
    // The compression ratio:
    // compression_ratio = max(1, size(tx.data) * 1e9 / size(compress(tx.data)))
    compression_ratio: U256,
    // The compressed size in bytes:
    // compressed_size = min(size(zstd(rlp(tx))), size(rlp(tx)))
    compressed_size: usize,
    // The raw encoded bytes of `value`, without compression.
    encoded_bytes: Bytes,
}

/// A trait for types that can be constructed from a transaction,
/// its sender, encoded bytes, compression ratio, and compressed size.
pub trait FromTxWithCompressionInfo<Tx> {
    /// Builds a `TxEnv` from a transaction, its sender, encoded transaction bytes,
    /// its compression ratio, and compressed size.
    fn from_tx_with_compression_info(
        tx: &Tx,
        sender: Address,
        encoded: Bytes,
        compression_ratio: Option<U256>,
        compressed_size: Option<usize>,
    ) -> Self;
}

impl<TxEnv, T> FromTxWithCompressionInfo<&T> for TxEnv
where
    TxEnv: FromTxWithCompressionInfo<T>,
{
    fn from_tx_with_compression_info(
        tx: &&T,
        sender: Address,
        encoded: Bytes,
        compression_ratio: Option<U256>,
        compressed_size: Option<usize>,
    ) -> Self {
        TxEnv::from_tx_with_compression_info(
            tx,
            sender,
            encoded,
            compression_ratio,
            compressed_size,
        )
    }
}

impl<T, TxEnv: FromTxWithCompressionInfo<T>> ToTxEnv<TxEnv> for WithCompressionInfo<Recovered<T>> {
    fn to_tx_env(&self) -> TxEnv {
        let recovered = &self.value;
        TxEnv::from_tx_with_compression_info(
            recovered.inner(),
            recovered.signer(),
            self.encoded_bytes.clone(),
            Some(self.compression_ratio),
            Some(self.compressed_size),
        )
    }
}

impl<T, TxEnv: FromTxWithCompressionInfo<T>> ToTxEnv<TxEnv> for WithCompressionInfo<&Recovered<T>> {
    fn to_tx_env(&self) -> TxEnv {
        let recovered = &self.value;
        TxEnv::from_tx_with_compression_info(
            recovered.inner(),
            *recovered.signer(),
            self.encoded_bytes.clone(),
            Some(self.compression_ratio),
            Some(self.compressed_size),
        )
    }
}

impl FromTxWithCompressionInfo<ScrollTxEnvelope> for ScrollTransactionIntoTxEnv<TxEnv> {
    fn from_tx_with_compression_info(
        tx: &ScrollTxEnvelope,
        caller: Address,
        encoded: Bytes,
        compression_ratio: Option<U256>,
        compressed_size: Option<usize>,
    ) -> Self {
        let base = match &tx {
            ScrollTxEnvelope::Legacy(tx) => TxEnv::from_recovered_tx(tx.tx(), caller),
            ScrollTxEnvelope::Eip2930(tx) => TxEnv::from_recovered_tx(tx.tx(), caller),
            ScrollTxEnvelope::Eip1559(tx) => TxEnv::from_recovered_tx(tx.tx(), caller),
            ScrollTxEnvelope::Eip7702(tx) => TxEnv::from_recovered_tx(tx.tx(), caller),
            ScrollTxEnvelope::L1Message(tx) => {
                let TxL1Message { to, value, gas_limit, input, queue_index: _, sender: _ } = &**tx;
                TxEnv {
                    tx_type: tx.ty(),
                    caller,
                    gas_limit: *gas_limit,
                    kind: TxKind::Call(*to),
                    value: *value,
                    data: input.clone(),
                    gas_price: 0,
                    gas_priority_fee: None,
                    chain_id: None,
                    nonce: 0,
                    access_list: Default::default(),
                    blob_hashes: Default::default(),
                    max_fee_per_blob_gas: Default::default(),
                    authorization_list: Default::default(),
                }
            }
        };

        Self::new(base, Some(encoded), compression_ratio, compressed_size)
    }
}

/// A trait that allows a type to be converted into [`WithCompressionInfo`].
pub trait ToTxWithCompressionInfo<Tx> {
    /// Converts the type into a [`WithCompressionInfo`] instance using the provided compression
    /// ratio and compressed size.
    fn with_compression_info(
        &self,
        compression_ratio: U256,
        compressed_size: usize,
    ) -> WithCompressionInfo<Recovered<&Tx>>;
}

impl<Tx: Encodable2718> ToTxWithCompressionInfo<Tx> for Recovered<&Tx> {
    fn with_compression_info(
        &self,
        compression_ratio: U256,
        compressed_size: usize,
    ) -> WithCompressionInfo<Recovered<&Tx>> {
        let encoded_bytes = self.inner().encoded_2718();
        WithCompressionInfo {
            value: *self,
            compression_ratio,
            compressed_size,
            encoded_bytes: encoded_bytes.into(),
        }
    }
}

impl<Tx, T: RecoveredTx<Tx>> RecoveredTx<Tx> for WithCompressionInfo<T> {
    fn tx(&self) -> &Tx {
        self.value.tx()
    }

    fn signer(&self) -> &Address {
        self.value.signer()
    }
}

#[cfg(test)]
mod tests {
    use crate::compute_compressed_size;

    use super::compute_compression_ratio;
    use alloy_primitives::{bytes, uint, U256};

    #[test]
    fn test_compression() -> eyre::Result<()> {
        // Compute compression ratio and compressed size for each test case.
        // These test cases are meant to be shared between the Go and Rust implementations.
        // Note: Feynman's compression ratio is computed on the transaction payload,
        // while Galileo's compressed size is computed on the full RLP-encoded transaction.
        // In these compression tests we ignore this distinction.

        // eth-transfer
        let bytes = bytes!("0x");
        let ratio = compute_compression_ratio(&bytes);
        let size = compute_compressed_size(&bytes);
        assert_eq!(ratio, U256::MAX); // empty data is infinitely compressible by definition
        assert_eq!(size, 0);

        // scr-transfer
        // https://scrollscan.com/tx/0x7b681ce914c9774aff364d2b099b2ba41dea44bcd59dbebb9d4c4b6853893179
        let bytes = bytes!("0xa9059cbb000000000000000000000000687b50a70d33d71f9a82dd330b8c091e4d77250800000000000000000000000000000000000000000000000ac96dda943e512bb9");
        let ratio = compute_compression_ratio(&bytes);
        let size = compute_compressed_size(&bytes);
        assert_eq!(ratio, U256::from(1_387_755_102u64)); // 1.4x
        assert_eq!(size, 49);

        // syncswap-swap
        // https://scrollscan.com/tx/0x59a7b72503400b6719f3cb670c7b1e7e45ce5076f30b98bdaad3b07a5d0fbc02
        let bytes = bytes!("");
        let ratio = compute_compression_ratio(&bytes);
        let size = compute_compressed_size(&bytes);
        assert_eq!(ratio, U256::from(4_857_142_857u64)); // 4.8x
        assert_eq!(size, 126);

        // uniswap-swap
        // https://scrollscan.com/tx/0x65b268bd8ef416f44983ee277d748de044243272b0f106b71ff03cc8501a05da
        let bytes = bytes!("");
        let ratio = compute_compression_ratio(&bytes);
        let size = compute_compressed_size(&bytes);
        assert_eq!(ratio, U256::from(2_620_689_655u64)); // 2.6x
        assert_eq!(size, 87);

        // etherfi-deposit
        // https://scrollscan.com/tx/0x41a77736afd54134b6c673e967c9801e326495074012b4033bd557920cbe5a71
        let bytes = bytes!("");
        let ratio = compute_compression_ratio(&bytes);
        let size = compute_compressed_size(&bytes);
        assert_eq!(ratio, U256::from(1_788_944_723u64)); // 1.8x
        assert_eq!(size, 199);

        // etherfi-stargate
        // https://scrollscan.com/tx/0x08bf18e860d4770920ba838fe709ca202227aa9afea1b0c11314e7f41fc5f578
        let bytes =
            bytes!("0x5988e7a1000000000000000000000000388325dd7c76e37cfda1ed6d8a97849a46b5512a");
        let ratio = compute_compression_ratio(&bytes);
        let size = compute_compressed_size(&bytes);
        assert_eq!(ratio, U256::from(1_000_000_000)); // 1x
        assert_eq!(size, 36);

        // etherfi-openocean
        // https://scrollscan.com/tx/0xba29777d4135cb1b1dc462f07d486ad589dd3de74b8a5a64e9ff070cef0db35a
        let bytes = bytes!("");
        let ratio = compute_compression_ratio(&bytes);
        let size = compute_compressed_size(&bytes);
        assert_eq!(ratio, uint!(8_992_608_236_U256)); // 9x
        assert_eq!(size, 947);

        // edgepushoracle-postupdate
        // https://scrollscan.com/tx/0x8271c68146a3b07b1ebf52ce0b550751f49cbd72fa0596ef14ff56d1f23a0bec
        let bytes = bytes!("");
        let ratio = compute_compression_ratio(&bytes);
        let size = compute_compressed_size(&bytes);
        assert_eq!(ratio, U256::from(2_441_805_225u64)); // 2.4x
        assert_eq!(size, 421);

        // intmax-post
        // https://scrollscan.com/tx/0x7244e27223cdd79ba0f0e3990c746e5d524e35dbcc200f0a7e664ffdc6d08eef
        let bytes = bytes!("");
        let ratio = compute_compression_ratio(&bytes);
        let size = compute_compressed_size(&bytes);
        assert_eq!(ratio, U256::from(1_298_578_199u64)); // 1.3x
        assert_eq!(size, 422);

        // galileo-mismatch
        // https://scrollscan.com/tx/0x773daae3ac1d31cf0ac76dc25504fe76ad5458c7df9578161898b73bd8039c90
        let bytes = bytes!("");
        let ratio = compute_compression_ratio(&bytes);
        let size = compute_compressed_size(&bytes);
        assert_eq!(ratio, U256::from(1_438_538_205u64)); // 1.4x
        assert_eq!(size, 301);

        Ok(())
    }
}
